// Deterministic simulation helpers are independent from the DOM renderer.
let rngSeed=CONFIG.seed;
const random=()=>{rngSeed=(rngSeed*1664525+1013904223)>>>0;return rngSeed/4294967296};
const int=(a,b)=>Math.floor(random()*(b-a+1))+a;
const clamp=(n,a,b)=>Math.max(a,Math.min(b,n));
const classOf=id=>DATA.classes.find(c=>c.id===id)||DATA.classes[0];
const itemOf=id=>DATA.items.find(i=>i.id===id);
const statSum=(cat,s)=>cat.stats[s]+(classOf(cat.classId).stats[s]||0)+(cat.item&&itemOf(cat.item)?.stat===s?itemOf(cat.item).amount:0);
const aliveCats=()=>state.cats.filter(c=>!c.retired&&c.age>=2&&c.hp>0);
const partyCats=()=>state.party.map(id=>state.cats.find(c=>c.id===id)).filter(Boolean);
const statKeys=['STR','DEX','CON','INT','CHA','SPD','LCK'];
const namesA=['Moldy','Deputy','Gum','Beans','Mister','Soggy','Crumb','Wiggle','Tax','Meatball','Little','Chairman','Puddle','Nurse','Bad'];
const namesB=['Biscuits','Wednesday','Clawdia','Mittens','Gravy','Scream','Toaster','Pickle','Gary','Biscuit Jr.','The Vague','Dirtbag','Moth','Oatmeal','Tuna'];
const catName=()=>`${namesA[int(0,namesA.length-1)]} ${namesB[int(0,namesB.length-1)]}`;
let nextId=20;
const makeCat=(name,age=3,parents=[])=>({id:nextId++,name,age,classId:DATA.classes[int(0,DATA.classes.length-1)].id,stats:Object.fromEntries(statKeys.map(s=>[s,parents.length?clamp(Math.round((parents[0].stats[s]+parents[1].stats[s])/2)+int(-1,1),3,7):int(3,7)])),color:['#b3261e','#7c8f3a','#5b3a6b','#d9b84a','#7f6a52'][int(0,4)],mutation:random()<.23?['third eye','wonky ears','bandaged mouth','spoon tail'][int(0,3)]:null,ageLabel:age<2?'kitten':'adult',hp:CONFIG.playerBaseHealth,retired:false,item:null,mood:3});
const initialCats=[['Deputy Biscuits','scrapper'],['Moldy Mittens','mender'],['Crumb Scream','slink'],['Chairman Tuna','oracle']].map(([name,classId],i)=>{const c=makeCat(name,3);c.classId=classId;c.stats=Object.fromEntries(statKeys.map(s=>[s,[6,4,5,5,6,5,4][(i+statKeys.indexOf(s))%7]]));c.color=['#b3261e','#7c8f3a','#5b3a6b','#d9b84a'][i];return c});
let state={day:CONFIG.startingDay,food:CONFIG.startingFood,scrap:CONFIG.startingScrap,mood:3,cleanliness:2,comfort:2,cats:initialCats,party:[],mode:'house',run:null,phase:'',log:['Day one. The landlord has left you one room and a note that says “don’t feed the wall.”'],breedLog:[],selectedCat:null,selectedUnit:null,round:1,track:0,radio:false,winCount:0};
const $=s=>document.querySelector(s);
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function log(text){state.log.unshift(text);state.log=state.log.slice(0,35)}
function toast(text){const e=$('#toast');e.textContent=text;e.classList.add('show');setTimeout(()=>e.classList.remove('show'),CONFIG.toastDurationMs)}
function catSvg(cat,size='100%'){
 const c=cat.color||'#7c8f3a',eye='#fffdf5',mutation=cat.mutation;
 const extra=mutation==='third eye'?'<ellipse cx="50" cy="31" rx="8" ry="10" fill="#fffdf5" stroke="#151210" stroke-width="3"/><circle cx="50" cy="32" r="3" fill="#151210"/>':'';
 const ears=mutation==='wonky ears'?'<path d="M26 39 Q18 6 36 26 M64 27 Q78 -2 73 35" fill="'+c+'" stroke="#151210" stroke-width="4" stroke-linejoin="round"/>':'<path d="M26 40 Q18 11 39 28 L50 38 62 27 Q82 9 74 40" fill="'+c+'" stroke="#151210" stroke-width="4" stroke-linejoin="round"/>';
 const tail=mutation==='spoon tail'?'<path d="M67 71 Q93 59 84 39" fill="none" stroke="#151210" stroke-width="8" stroke-linecap="round"/><ellipse cx="84" cy="35" rx="8" ry="11" fill="'+c+'" stroke="#151210" stroke-width="3"/>':'<path d="M67 72 Q93 70 84 49" fill="none" stroke="#151210" stroke-width="8" stroke-linecap="round"/>';
 const mouth=mutation==='bandaged mouth'?'<path d="M40 57 L60 57 M40 53 L60 53 M40 61 L60 61" stroke="#ede6d6" stroke-width="4"/>':'<path d="M46 51 Q50 55 54 51 M50 53 Q48 61 43 60 M50 53 Q53 61 58 59" fill="none" stroke="#151210" stroke-width="2.5" stroke-linecap="round"/>';
 return `<svg viewBox="0 0 100 100" width="${size}" height="${size}" aria-label="${esc(cat.name)}"><path d="M34 76 Q23 82 25 94 M64 78 Q76 82 73 94" fill="none" stroke="#151210" stroke-width="8" stroke-linecap="round"/><path d="M67 71 Q93 70 84 48" fill="none" stroke="#151210" stroke-width="8" stroke-linecap="round"/>${ears}<ellipse cx="50" cy="60" rx="32" ry="31" fill="${c}" stroke="#151210" stroke-width="4"/><path d="M32 46 Q40 40 46 47 M54 47 Q61 40 69 46" fill="none" stroke="#151210" stroke-width="3.5" stroke-linecap="round"/><ellipse cx="39" cy="53" rx="7" ry="9" fill="${eye}" stroke="#151210" stroke-width="2"/><ellipse cx="61" cy="53" rx="7" ry="9" fill="${eye}" stroke="#151210" stroke-width="2"/><ellipse cx="40" cy="55" rx="2.7" ry="4" fill="#151210"/><ellipse cx="60" cy="55" rx="2.7" ry="4" fill="#151210"/><path d="M47 64 Q50 61 53 64 Q50 69 47 64" fill="#b3261e" stroke="#151210" stroke-width="1.5"/>${mouth}${extra}<path d="M29 70 Q50 78 71 69" fill="none" stroke="#151210" stroke-width="2" opacity=".55"/></svg>`;
}
function showModal(title,body,buttons){const root=document.createElement('div');root.className='modal-backdrop';root.innerHTML=`<div class="modal"><span class="eyebrow">BOON COUNTY NOTICE</span><h2>${title}</h2><div>${body}</div><div class="modal-actions">${buttons.map((b,i)=>`<button class="btn ${i===buttons.length-1?'btn-primary':''}" data-modal="${i}">${b.label}</button>`).join('')}</div></div>`;root.addEventListener('click',e=>{if(e.target===root)root.remove();const b=e.target.closest('[data-modal]');if(b){const fn=buttons[+b.dataset.modal].run;root.remove();fn?.()}});document.body.appendChild(root)}
function render(){ $('#day-label').textContent=`DAY ${String(state.day).padStart(2,'0')}`;$('#game-root').innerHTML=state.mode==='battle'?renderBattle():renderHouse();$('#sound-toggle').classList.toggle('sound-playing',state.radio); }
function renderHouse(){
 const available=aliveCats();const selected=state.party;
 const catCards=state.cats.map(c=>{const adult=c.age>=2&&!c.retired;return `<article class="cat-card ${selected.includes(c.id)?'selected':''} ${c.retired?'retired':''}"><div class="cat-avatar">${catSvg(c)}</div><div><div class="cat-name">${esc(c.name)} ${c.mutation?`<span class="condition">${esc(c.mutation)}</span>`:''}</div><div class="cat-meta">${c.retired?'RETIRED · LOCAL LEGEND':c.age<2?`KITTEN · GROWS IN ${2-c.age} NIGHT${2-c.age===1?'':'S'}`:`${classOf(c.classId).name.toUpperCase()} · HP ${c.hp}/${CONFIG.playerBaseHealth}`}</div><div class="cat-stats">${statKeys.map(s=>`<span>${s} ${c.stats[s]}</span>`).join('')}</div></div><div class="cat-controls">${adult?`<select class="class-select" data-class="${c.id}" aria-label="${esc(c.name)} collar">${DATA.classes.map(k=>`<option value="${k.id}" ${k.id===c.classId?'selected':''}>${k.icon} ${k.name}</option>`).join('')}</select><input class="cat-check" type="checkbox" data-party="${c.id}" ${selected.includes(c.id)?'checked':''} aria-label="Select ${esc(c.name)} for expedition">`:''}</div></article>`}).join('');
 const cats=state.cats.filter(c=>!c.retired);const feedBtn=state.food>=CONFIG.feedFoodCost&&cats.length>0;
 return `<div class="section-head"><div><div class="eyebrow">YOUR HOUSE · DAY ${String(state.day).padStart(2,'0')}</div><h1 class="section-title">A home for weirdos.</h1><div class="subtitle">Raise a lineage. Equip a collar. Try not to let the carpet become sentient.</div></div><div class="resources"><span class="pill">🥫 ${state.food} FOOD</span><span class="pill">⚙ ${state.scrap} SCRAP</span><span class="pill">☀ ${state.cats.filter(c=>!c.retired).length}/${CONFIG.catLimit} CATS</span></div></div>
 <div class="layout"><section class="panel house-panel"><div class="panel-head"><span class="panel-title">THE HOUSE ON GUTTER LANE</span><span class="room-banner">ROOM TEMPERATURE: CONCERNING</span></div><div class="house-scene"><div class="wallpaper"></div><span class="room-label">LIVING ROOM / POSSIBLE PORTAL</span><span class="sun">☼</span><div class="window"></div><div class="house-shelf"></div><span class="plant">♣</span><span class="furniture furn-radio" title="Radio: ${DATA.tracks[state.track%DATA.tracks.length]}">📻</span><span class="furniture furn-cushion">🛋</span><span class="furniture furn-bowl">🥣</span><span class="furniture furn-litter">🪣</span><div class="house-floor"></div>${cats.slice(0,4).map((c,i)=>`<div class="cat-in-room" style="left:${22+i*16}%;animation-delay:${i*-.55}s">${catSvg(c)}</div>`).join('')}</div><div class="house-stats">${[['MOOD',state.mood],['CLEANLINESS',state.cleanliness],['COMFORT',state.comfort]].map(([n,v])=>`<div><div class="stat-line"><span>${n}</span><b>${v}/5</b></div><div class="stat-track"><div class="stat-fill" style="width:${v*20}%"></div></div></div>`).join('')}</div><div class="small-section"><h3 class="small-title">Tonight’s domestic situation</h3><div class="muted">A family may be formed off-screen. Any unattended food will be considered a shared hallucination. Fights are non-binding unless someone starts a spreadsheet.</div></div></section>
 <aside class="panel side-panel"><div class="panel-head"><span class="panel-title">THE HOUSEHOLD</span><span class="panel-kicker">${available.length} ADULTS READY</span></div><div class="cats-heading"><span>Lineage roster</span><span class="panel-kicker">${state.cats.length}/${CONFIG.catLimit}</span></div><div class="cat-list">${catCards||'<div class="empty-note">No cats. This is technically a problem.</div>'}</div><div class="small-section"><h3 class="small-title">Make a tiny person</h3><div class="breed-row"><select id="parent-a" aria-label="First parent">${available.map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('')}</select><span>×</span><select id="parent-b" aria-label="Second parent">${available.map((c,i)=>`<option value="${c.id}" ${i===1?'selected':''}>${esc(c.name)}</option>`).join('')}</select><button class="btn btn-small" data-action="breed" ${available.length<2||state.food<CONFIG.breedingFoodCost||state.cats.length>=CONFIG.catLimit?'disabled':''}>BREED · ${CONFIG.breedingFoodCost}🥫</button></div><div class="breed-log">${state.breedLog.slice(-2).reverse().map(esc).join('<br>')||'The stork is on a smoke break.'}</div></div><div class="side-actions"><div class="action-row"><button class="btn" data-action="feed" ${feedBtn?'':'disabled'}>Feed the horde · ${CONFIG.feedFoodCost}🥫</button><button class="btn" data-action="furniture" ${state.scrap<2?'disabled':''}>Fix the radio · 2⚙</button></div><button class="btn btn-primary" data-action="night">End day &amp; let the night happen</button><button class="btn btn-ink" data-action="start-expedition" ${selected.length<1?'disabled':''}>Prepare expedition · ${selected.length}/${CONFIG.partyLimit} selected →</button><div class="muted">Adventure cats return retired. If the whole party falls, their gear and run loot go with them.</div></div></aside></div>`;
}

