+function renderBattle(){
+ const r=state.run, party=partyCats();if(!r)return '<div>Loading the expedition...</div>';
+ const units=[...party.map(c=>({id:c.id,kind:'cat',name:c.name,x:c.x,y:c.y,hp:c.runHp,max:c.maxHp,dead:c.runHp<=0,ref:c})),...r.enemies.map(e=>({id:e.id,kind:'enemy',name:e.name,x:e.x,y:e.y,hp:e.hp,max:e.maxHp,dead:e.hp<=0,ref:e}))];
+ const picked=units.find(u=>u.id===state.selectedUnit);const board=Array.from({length:CONFIG.gridSize*CONFIG.gridSize},(_,n)=>{const x=n%CONFIG.gridSize,y=Math.floor(n/CONFIG.gridSize),type=r.tiles[n],unit=units.find(u=>u.x===x&&u.y===y&&!u.dead);let cls=type==='junk'?'junk':type==='hazard'?'hazard':type==='cover'?'cover':type==='rug'?'rug':'';if(picked?.kind==='cat'&&state.phase==='player'&&picked.ref.runHp>0&&!unit){const dist=Math.abs(x-picked.x)+Math.abs(y-picked.y);if(dist>0&&dist<=picked.ref.move&&!r.moved.includes(picked.id))cls+=' move-range'}if(picked?.kind==='cat'&&unit?.kind==='enemy'&&unit.hp>0&&Math.abs(x-picked.x)+Math.abs(y-picked.y)<=picked.ref.range&&!r.acted.includes(picked.id))cls+=' attack-range';return `<div class="tile ${cls} ${picked&&picked.x===x&&picked.y===y?'selected':''}" data-tile="${x},${y}" title="${type==='hazard'?'Mystery puddle — hurts to stand in':type==='junk'?'Junk pile — impassable':type==='cover'?'Cardboard cover':type}">${unit?`<div class="token ${unit.kind==='enemy'?'enemy':''} ${unit.dead?'dead':''}" data-unit="${unit.id}">${unit.kind==='cat'?catSvg(unit.ref):enemySvg(unit.ref)}<div class="hp-mini"><span style="width:${Math.max(0,unit.hp/unit.max*100)}%;background:${unit.kind==='cat'?'#7c8f3a':'#b3261e'}"></span></div></div>`:''}</div>`}).join('');
+ const aliveEnemies=r.enemies.filter(e=>e.hp>0),selected=picked?.kind==='cat'?picked.ref:null;
+ return `<div class="section-head"><div><div class="eyebrow">EXPEDITION ${String(r.stage).padStart(2,'0')} · ${r.nodeName.toUpperCase()}</div><h1 class="section-title">${esc(r.title)}</h1><div class="subtitle">${r.boss?'The mayor has unionized the mold. This is going to be awkward.':'The county is full of things that should have stayed in the bin.'}</div></div><div class="resources"><span class="pill">✦ ${r.xp} XP</span><span class="pill">🥫 ${r.lootFood} FOUND</span><span class="pill">⚙ ${r.lootScrap} FOUND</span></div></div>
+ <div class="game-layout"><section class="panel battle-panel"><div class="battle-top"><div><div class="battle-title">${r.boss?'Mayor Mold’s Basement':'The Unlicensed Dump'}</div><div class="battle-subtitle">10 × 10 COUNTY-APPROVED CAT SCRAPING GRID</div></div><span class="tag">${state.phase==='player'?`YOUR TURN · ${state.round}`:'THEIR TURN...'}</span></div><div class="battle-board">${board}</div><div class="battle-legend"><div class="legend-left"><span class="legend-item"><span class="legend-swatch"></span> YOUR CATS</span><span class="legend-item"><span class="legend-swatch red"></span> BAD NEIGHBORS</span><span>〰 SLIPPERY NON-REGULATION FLOOR</span></div><span class="turn-pill">${aliveEnemies.length} FOE${aliveEnemies.length===1?'':'S'} LEFT</span></div></section><aside class="combat-side"><div class="combat-card"><h3>On the payroll</h3>${party.map(c=>`<div class="unit-row"><div class="unit-portrait">${catSvg(c)}</div><div class="unit-details"><div class="unit-name">${esc(c.name)} ${r.acted.includes(c.id)?'· DONE':''}</div><div class="unit-hp">${Math.max(0,c.runHp)} / ${c.maxHp} HP · ${classOf(c.classId).name}</div><div class="hp-track"><span style="width:${clamp(c.runHp/c.maxHp*100,0,100)}%"></span></div></div></div>`).join('')}</div><div class="combat-card"><h3>Selected cat</h3><div class="selected-info">${selected?`<b>${esc(selected.name)}</b> · ${classOf(selected.classId).skill}<br>${classOf(selected.classId).skillText}<br><span class="mono">${r.acted.includes(selected.id)?'ACTION SPENT':'TAP A GREEN TILE TO MOVE, A RED ONE TO ATTACK'}</span>`:'Tap one of your cats on the board to issue an order.'}</div><div class="controls" style="margin-top:11px"><button class="btn btn-primary" data-action="skill" ${!selected||r.acted.includes(selected.id)||state.phase!=='player'?'disabled':''}>Use collar skill</button><button class="btn" data-action="attack" ${!selected||r.acted.includes(selected.id)||state.phase!=='player'?'disabled':''}>Attack nearest</button><button class="btn" data-action="end-turn" ${state.phase!=='player'?'disabled':''}>End cat turn →</button></div></div><div class="combat-card"><h3>Field report</h3><div class="combat-log">${state.log.slice(0,7).map(x=>`<div>${esc(x)}</div>`).join('')}</div></div></aside></div>`;
+}
+function enemySvg(e){const color=e.color||'#7c8f3a',boss=e.boss;return `<svg viewBox="0 0 100 100" aria-label="${esc(e.name)}"><path d="M22 48 Q18 18 43 29 Q59 16 77 36 L83 61 Q76 86 48 82 Q19 78 22 48" fill="${color}" stroke="#151210" stroke-width="5"/><path d="M29 36 L20 18 42 27 M64 28 L80 17 75 40" fill="${color}" stroke="#151210" stroke-width="5" stroke-linejoin="round"/><ellipse cx="39" cy="49" rx="8" ry="10" fill="#fffdf5" stroke="#151210" stroke-width="3"/><ellipse cx="63" cy="49" rx="8" ry="10" fill="#fffdf5" stroke="#151210" stroke-width="3"/><circle cx="41" cy="51" r="3"/><circle cx="65" cy="51" r="3"/><path d="M44 65 Q53 58 61 66 Q54 77 44 65" fill="#151210"/>${boss?'<path d="M29 28 L32 9 44 26 M55 25 L68 6 69 31" fill="#d9b84a" stroke="#151210" stroke-width="4"/>':''}</svg>`}

