function beginRun(){
 if(state.party.length<1||state.party.length>CONFIG.partyLimit)return toast('Choose between one and four adult cats first.');
 state.cats.filter(c=>state.party.includes(c.id)).forEach(c=>{c.runHp=clamp(CONFIG.playerBaseHealth+statSum(c,'CON')-5,8,18);c.maxHp=c.runHp;c.x=1+int(0,1);c.y=3+state.party.indexOf(c.id)*2;c.move=clamp(CONFIG.baseMove+Math.floor((statSum(c,'SPD')-5)/2),2,5);c.range=c.classId==='slink'?3:1});
 state.mode='battle';state.run={stage:1,xp:0,lootFood:0,lootScrap:0,boss:false,enemies:[],moved:[],acted:[],tiles:makeTiles()};state.selectedUnit=state.party[0];state.round=1;state.phase='player';spawnEncounter();log('The party leaves the house. The house immediately gets quieter and somehow louder.');render();
}
function makeTiles(){const tiles=Array(CONFIG.gridSize**2).fill('floor');for(let i=0;i<8;i++){const x=int(2,7),y=int(0,9);if((x<3&&y>=3&&y<=8)||(x>6&&y>5))continue;tiles[y*CONFIG.gridSize+x]=random()<.58?'junk':random()<.5?'cover':'hazard'}for(let i=0;i<12;i++){const n=int(0,tiles.length-1);if(tiles[n]==='floor')tiles[n]='rug'}return tiles}
function spawnEncounter(){const r=state.run;r.boss=r.stage>=3;r.nodeName=r.boss?'Boss fight':`Encounter ${r.stage}`;r.title=r.boss?'The Mold Has A Mayor':'County Line Problems';r.tiles=makeTiles();const cats=partyCats();cats.forEach((c,i)=>{c.x=1;c.y=Math.min(8,2+i*2)});const types=r.boss?['mayor-mold']:r.stage===2?['bin-rat','sock-wraith','trash-goblin']:['trash-goblin','sock-wraith','trash-goblin'];r.enemies=types.map((id,i)=>{const template=DATA.enemies.find(e=>e.id===id);const scale=r.stage===1?1:r.stage===2?1.18:1;return {...template,id:`${id}-${r.stage}-${i}`,maxHp:Math.round(template.health*scale),hp:Math.round(template.health*scale),x:7+((i%2)*2),y:2+i*3,damage:Math.ceil(template.damage*scale)}});r.moved=[];r.acted=[];state.selectedUnit=state.party[0];state.phase='player';state.round=1;log(r.boss?'Mayor Mold emerges from a bin marked “not a throne.”':'The bad neighbors arrive. They have very poor paperwork.');render()}
