function weightedStat(a,b,stim){const high=Math.max(a,b),low=Math.min(a,b);const favored=clamp((100+stim)/(200+Math.abs(stim)),0,1);return random()<favored?high:low}
function kittenFrom(a,b){
 const stats=Object.fromEntries(statKeys.map(s=>[s,clamp(weightedStat(a.stats[s],b.stats[s],state.stimulation||0)+int(-1,1),3,7)]));
